    ofb0_S_Vc_TValid_s(0)           <= nchar0_M_Link_Valid_s;

    -- Connection c4: ofb0.M_Vc[0] to nchar0.S_Link
    nchar0_S_Link_Data_s    <= ofb0_M_Vc_TData_s(127 downto 0);
    nchar0_S_Link_Keep_s    <= ofb0_M_Vc_TKeep_s(15 downto 0);
    nchar0_S_Link_Last_s    <= ofb0_M_Vc_TLast_s(0);
    ofb0_M_Vc_TReady_s(0)   <= nchar0_S_Link_Ready_s;
