    spp0_S_Link_User_s(0) <= ofb0_M_Vc_TUser_s(1);
    spp0_S_Link_Valid_s   <= ofb0_M_Vc_TValid_s(1);

    -- Connection c11: spp0.M_Rx[0] to frm0.S_In
    frm0_S_In_Data_s     <= spp0_M_Rx_Data_s(127 downto 0);
    frm0_S_In_Keep_s     <= spp0_M_Rx_Keep_s(15 downto 0);
    frm0_S_In_Last_s     <= spp0_M_Rx_Last_s(0);
    spp0_M_Rx_Ready_s(0) <= frm0_S_In_Ready_s;
    frm0_S_In_Valid_s    <= spp0_M_Rx_Valid_s(0);

    -- Connection c40: dec0.M_AxiLite[7] to ofb0.S_AxiLite
    ofb0_S_AxiLite_ArAddr_s                <= dec0_M_AxiLite_ArAddr_s(123 downto 112);
    dec0_M_AxiLite_ArReady_s(7)            <= ofb0_S_AxiLite_ArReady_s;
    ofb0_S_AxiLite_ArValid_s               <= dec0_M_AxiLite_ArValid_s(7);
    ofb0_S_AxiLite_AwAddr_s                <= dec0_M_AxiLite_AwAddr_s(123 downto 112);
    dec0_M_AxiLite_AwReady_s(7)            <= ofb0_S_AxiLite_AwReady_s;
    ofb0_S_AxiLite_AwValid_s               <= dec0_M_AxiLite_AwValid_s(7);
    ofb0_S_AxiLite_BReady_s                <= dec0_M_AxiLite_BReady_s(7);
    dec0_M_AxiLite_BResp_s(15 downto 14)   <= ofb0_S_AxiLite_BResp_s;
    dec0_M_AxiLite_BValid_s(7)             <= ofb0_S_AxiLite_BValid_s;
    dec0_M_AxiLite_RData_s(255 downto 224) <= ofb0_S_AxiLite_RData_s;
    ofb0_S_AxiLite_RReady_s                <= dec0_M_AxiLite_RReady_s(7);
    dec0_M_AxiLite_RResp_s(15 downto 14)   <= ofb0_S_AxiLite_RResp_s;
    dec0_M_AxiLite_RValid_s(7)             <= ofb0_S_AxiLite_RValid_s;
    ofb0_S_AxiLite_WData_s                 <= dec0_M_AxiLite_WData_s(255 downto 224);
    dec0_M_AxiLite_WReady_s(7)             <= ofb0_S_AxiLite_WReady_s;
    ofb0_S_AxiLite_WStrb_s                 <= dec0_M_AxiLite_WStrb_s(31 downto 28);
    ofb0_S_AxiLite_WValid_s                <= dec0_M_AxiLite_WValid_s(7);

    -----------------------------------------------------------------------------------------------
    -- Tie-offs
    -----------------------------------------------------------------------------------------------
    -- ofb0.S_Bc is not connected.
    ofb0_S_Bc_TData_s  <= (others => '0');
    ofb0_S_Bc_TUser_s  <= (others => '0');
    ofb0_S_Bc_TValid_s <= '0';

    -- ofb0.M_Bc is not connected.
    ofb0_M_Bc_TReady_s <= '0';

    -- Constant of frm0.Cfg: Key slot 0.
    frm0_Cfg_Slot_s <= "00";

    -- Constant of frm1.Cfg: Key slot 0.
    frm1_Cfg_Slot_s <= "00";

    -- Constant of frm2.Cfg: Key slot 0.
    frm2_Cfg_Slot_s <= "00";

    -- Constant of frm3.Cfg: Key slot 0.
    frm3_Cfg_Slot_s <= "00";

    -----------------------------------------------------------------------------------------------
    -- Top-level ports
    -----------------------------------------------------------------------------------------------
    -- Top-level ports of pa0.Gt
    pa0_Gt_TxP   <= pa0_Gt_TxP_s;
    pa0_Gt_TxN   <= pa0_Gt_TxN_s;
    pa0_Gt_RxP_s <= pa0_Gt_RxP;
    pa0_Gt_RxN_s <= pa0_Gt_RxN;

end architecture;
